Contract GenerateLoanLetterAndAgreementModule::createLoanAccount(loanaccountid:Integer,balance:Real,status:LoanAccountStatus[NORMAL|HASPAIDINFULL]): Boolean {
          definition:
          ob:LoanAccount = LoanAccount.allInstance()->any(o | o.LoanAccountID = loanaccountid)

            precondition:
          (ob.oclIsUndefined() = true) or (ob.LoanAccountID = loanaccountid)

            postcondition:
          let newOb:LoanAccount in (newOb.oclIsNew() and newOb.LoanAccountID = loanaccountid and newOb.Balance = balance and newOb.Status = status and LoanAccount.allInstance()->includes(newOb) and result = true)

        }
